"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["93562"],{54009(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_valor_dominio.codigo_obrigatorio","status":422,"titulo":"C\xf3digo do valor de dom\xednio \xe9 obrigat\xf3rio"},"descricao":{"codigo":"uniplus.configuracao.fato_valor_dominio.codigo_obrigatorio","requisitos":["UNI-REQ-0065"],"oQueAconteceu":["O administrador acrescentou um valor a um fato do cat\xe1logo (`POST /api/configuracao/admin/fatos-candidato/{id}/valores`) com o campo `codigo` presente no JSON, mas vazio ou s\xf3 com espa\xe7os. O c\xf3digo \xe9 o que identifica o valor dentro do fato: a descri\xe7\xe3o e a orienta\xe7\xe3o s\xe3o o texto que o candidato l\xea, mas \xe9 o c\xf3digo que as regras, os formul\xe1rios e as demais opera\xe7\xf5es sobre o valor citam (UNI-REQ-0065).","A recusa vem na lista `errors` da resposta, com `field` igual a `codigo`. Se o corpo tiver outros problemas, cada um vem numa entrada pr\xf3pria da mesma resposta, e nada \xe9 gravado. A busca do fato vem antes da confer\xeancia do corpo: com um `{id}` que n\xe3o existe, a resposta \xe9 a de fato n\xe3o encontrado (`uniplus.configuracao.fato_candidato.nao_encontrado`), e n\xe3o esta.","Este c\xf3digo n\xe3o cobre o `codigo` ausente do JSON nem enviado como `null`. O corpo do acr\xe9scimo declara o c\xf3digo como texto n\xe3o anul\xe1vel (`ValorDominioInput.cs:4`), e o ASP.NET Core recusa o campo ausente ou nulo na valida\xe7\xe3o do modelo, com 400, antes de o pedido chegar ao tratamento do Uni+ e, portanto, antes da busca do fato. Essa recusa n\xe3o tem c\xf3digo do cat\xe1logo de erros do Uni+. S\xf3 o c\xf3digo presente, mas vazio ou em branco, chega \xe0 regra do dom\xednio e responde 422 com o c\xf3digo desta p\xe1gina. \xc9 o contr\xe1rio dos corpos que declaram o campo como anul\xe1vel de prop\xf3sito, para a aus\xeancia chegar ao dom\xednio (por exemplo, `CriarPrecedenciaFaseCommand.cs:13-16`)."],"comoResolver":["Envie o valor com o campo `codigo` presente e preenchido, de at\xe9 50 caracteres e que ainda n\xe3o exista no fato. Depois de acrescentado, o c\xf3digo do valor n\xe3o muda."],"ondeAparece":["Acr\xe9scimo de um valor a um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato valor dominio"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);